function Brand(){return <div className="brand"><div className="brand-mark"><Shield size={22}/><b>IS</b></div><div><div className="brand-name">INTELLISTACK <span>SYSTEMS</span></div></div></div>}
function appRoleFromProfile(profile){
  const platformRole=String(profile?.platform_role||'').toLowerCase();
  if(platformRole==='platform_owner'||platformRole==='platform_admin') return 'Super Admin';
  if(platformRole==='platform_support') return 'Help Desk Agent';
  const role=String(profile?.role||'').toLowerCase().replace(/[ -]+/g,'_');
  const roleMap={help_desk_agent:'Help Desk Agent',help_desk:'Help Desk Agent',it_administrator:'IT Administrator',security_agent:'Security Agent',governance_compliance:'Governance & Compliance',network_operations:'Network Operations'};
  return roleMap[role]||null;
}
function Login({onLogin,theme=defaultOrganizationTheme}) {
  const [accountType,setAccountType]=useState('individual');
  const [email,setEmail]=useState(()=>{try{return localStorage.getItem('intellistack-remembered-login-email')||'';}catch{return '';}});
  const [rememberEmail,setRememberEmail]=useState(()=>{try{return Boolean(localStorage.getItem('intellistack-remembered-login-email'));}catch{return false;}});
  const [password,setPassword]=useState('');
  const [showPassword,setShowPassword]=useState(false);
  const [provider,setProvider]=useState('');
  const [notice,setNotice]=useState('');
  const providers=[
    {name:'Microsoft 365',detail:'Work or school',mark:'▦'},
    {name:'Google Workspace',detail:'Business account',mark:'G'},
    {name:'Apple',detail:'Apple Account',mark:'●'},
    {name:'GitHub',detail:'Developer access',mark:'⌘'},
    {name:'SAML / SSO',detail:'Enterprise identity',mark:'◎'},
    {name:'More providers',detail:'Choose another method',mark:'•••'}
  ];
  const submitLogin=async(event)=>{
    event.preventDefault();
    setNotice('');
    if(!supabase){setNotice('Authentication is not configured yet. Add VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY to the Vercel project environment variables, then redeploy.');return;}
    if(!email.trim()||!password){setNotice('Enter your account email and password to continue.');return;}
    try{
      const {data,error}=await supabase.auth.signInWithPassword({email:email.trim(),password});
      if(error) throw error;
      const {data:profile,error:profileError}=await supabase.from('profiles').select('platform_role,role,display_name,email').eq('id',data.user.id).maybeSingle();
      if(profileError) throw new Error('Your credentials were accepted, but your account permissions could not be loaded. Check the profiles table SELECT policy for the signed-in user.');
      const assignedRole=appRoleFromProfile(profile);
      if(!assignedRole){await supabase.auth.signOut();setNotice('Your credentials were accepted, but this account has not been assigned an approved IntelliStack application role. Ask the platform owner to assign the role; no command-center access was granted.');return;}
      onLogin(assignedRole);
    }catch(error){setNotice(error?.message==='Invalid login credentials'?'Email or password is incorrect. Check the address and password created in Supabase.':(error?.message||'Sign-in failed. Check Supabase configuration and try again.'));}
  };
  const chooseProvider=(name)=>{
    setProvider(name);
    setNotice(name==='More providers'
      ? 'Additional methods can be enabled when their identity-provider configuration is added.'
      : name+' selected. Configure this provider in the authentication backend to complete sign-in.');
  };
  return <div className={'login-shell login-shell-v2 pattern-'+(theme.pattern||'none')+' gradient-'+(theme.gradient||'none')} style={{'--login-background':theme.images?.login?`linear-gradient(rgb(0 0 0 / ${(theme.imageOverlay||0)/100}),rgb(0 0 0 / ${(theme.imageOverlay||0)/100})),url(${theme.images.login})`:`url(${LoginImage})`,'--bg':theme.background,'--panel':theme.panel,'--panel2':theme.panelAlt,'--border':theme.border,'--text':theme.text,'--muted':theme.muted,'--cyan':theme.accent,'--blue':theme.secondaryAccent,'--radius':theme.cardRadius+'px','--theme-button-bg':theme.buttonBg,'--theme-button-text':theme.buttonText,'--theme-button-radius':theme.buttonRadius+'px','--theme-footer-bg':theme.footer,'--theme-footer-text':theme.footerText,'--theme-font-family':'\"'+(theme.fontFamily||'Inter')+'\",sans-serif','--theme-login-header-height':(theme.headerHeight||64)+'px','--theme-login-footer-height':(theme.footerHeight||58)+'px','--theme-login-padding':(theme.contentPadding||28)+'px'}}>
    <header className="login-header login-header-v2"><Brand/><div className="login-header-status"><span className="pulse"/> GLOBAL IT COMMAND CENTER</div></header>
    <main className="login-main login-main-v2">
      <section className="login-copy login-copy-v2">
        <div className="eyebrow"><span className="pulse"/> INTELLISTACK SYSTEMS</div>
        <h1><span>One World.</span><br/><em>One Intelligent Network.</em></h1>
        <p className="login-v2-subtitle">Technology. Security. People. A safer tomorrow.</p>
        <div className="login-v2-capabilities"><span><ShieldCheck size={16}/> Secure operations</span><span><Globe2 size={16}/> Global connectivity</span><span><Activity size={16}/> Always-on response</span></div>
      </section>
      <section className="login-card login-card-v2">
        <div className="card-top login-card-heading"><span className="eyebrow">SECURE ACCESS PORTAL</span><h2>Welcome back</h2><p>Sign in to your IntelliStack Systems account.</p></div>
        <div className="login-account-switch" role="group" aria-label="Account type">
          <button type="button" className={accountType==='individual'?'active individual':'individual'} onClick={()=>{setAccountType('individual');setNotice('');}}> <Users size={17}/><span><b>Individual</b><small>Personal account</small></span></button>
          <button type="button" className={accountType==='business'?'active business':'business'} onClick={()=>{setAccountType('business');setNotice('');}}> <Building2 size={17}/><span><b>Business</b><small>Organization account</small></span></button>
        </div>
        <form className="login-v2-form" onSubmit={submitLogin}>
          <label className="field-label">ACCOUNT PERMISSIONS</label>
          <div className="role-select-wrap"><ShieldCheck size={18}/><span>Your role is loaded from your assigned account permissions after sign-in.</span></div>
          <label className="field-label" htmlFor="login-email">{accountType==='business'?'BUSINESS EMAIL':'ACCOUNT EMAIL'}</label>
          <div className="input-wrap"><Users size={17}/><input id="login-email" type="email" autoComplete="username" placeholder="you@company.com" value={email} onChange={event=>{const nextEmail=event.target.value;setEmail(nextEmail);if(rememberEmail){try{if(nextEmail.trim())localStorage.setItem('intellistack-remembered-login-email',nextEmail.trim());else localStorage.removeItem('intellistack-remembered-login-email');}catch{}}}} required/></div>
          <label className="field-label" htmlFor="login-password">PASSWORD</label>
          <div className="input-wrap login-password-wrap"><LockKeyhole size={17}/><input id="login-password" type={showPassword?'text':'password'} autoComplete="current-password" placeholder="Enter your password" value={password} onChange={event=>setPassword(event.target.value)} required/><button className="password-toggle" type="button" onClick={()=>setShowPassword(value=>!value)}>{showPassword?'Hide':'Show'}</button></div>
          <div className="login-form-options"><label><input type="checkbox" checked={rememberEmail} onChange={event=>{const checked=event.target.checked;setRememberEmail(checked);try{if(checked){if(email.trim())localStorage.setItem('intellistack-remembered-login-email',email.trim());}else localStorage.removeItem('intellistack-remembered-login-email');}catch{}}}/> Remember my email on this device</label><button type="button" onClick={()=>setNotice('Password recovery will be available after Supabase Auth is connected.')}>Forgot password?</button></div>
          <button className="primary-btn full login-submit" type="submit">Sign in securely <span>→</span></button>
          <div className="login-or-divider"><span/> <b>OR CONTINUE WITH</b> <span/></div>
          <div className="login-provider-grid">{providers.map(item=><button type="button" key={item.name} className={'login-provider '+(provider===item.name?'selected':'')} onClick={()=>chooseProvider(item.name)}><span className={'login-provider-mark '+item.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}>{item.mark}</span><span><b>{item.name}</b><small>{item.detail}</small></span></button>)}</div>
          {notice&&<div className="login-auth-notice" role="status"><ShieldCheck size={15}/><span>{notice}</span></div>}
          <p className="login-auth-footnote"><LockKeyhole size={13}/> Secure sign-in is validated by Supabase Auth. Access depends on your assigned application role.</p>
        </form>
      </section>
    </main>
    <footer className="login-footer login-footer-v2"><span>© 2026 IntelliStack Systems</span><span><ShieldCheck size={13}/> Secure access <i/> Privacy <i/> Support</span><span><b>ONE WORLD.</b> ONE INTELLIGENT NETWORK.</span></footer>
  </div>;
}
function Metric({icon:Icon,label,value,trend,positive=true,onClick}){const content=<><div className="metric-top"><span>{label}</span><span className="metric-icon"><Icon size={18}/></span></div><div className="metric-value">{value}</div><div className={'metric-trend '+(positive?'good':'warn')}>{positive?<ArrowDownRight size={14}/>:<ArrowUpRight size={14}/>} {trend}</div>{onClick&&<span className="metric-drill">Explore details <span>↗</span></span>}</>;return onClick?<button type="button" className="metric-card metric-clickable" onClick={onClick} aria-label={label+': '+value+'. Explore details'}>{content}</button>:<div className="metric-card">{content}</div>}
function Panel({title,subtitle,children,action,className='',style}){return <section className={'panel '+className} style={style}><div className="panel-head"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>}
function Table({headers,rows}){return <div className="table-scroll"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows}</tbody></table></div>}
function StatusPill({children,kind='good'}){return <span className={'status-pill '+kind}><span/> {children}</span>}
const WORLD_TIME_ZONES = [
 {id:'America/Chicago',city:'Chicago',region:'US Central'},
 {id:'America/Los_Angeles',city:'Los Angeles',region:'US Pacific'},
 {id:'America/New_York',city:'New York',region:'US Eastern'},
 {id:'America/Sao_Paulo',city:'São Paulo',region:'Brazil'},
 {id:'Europe/London',city:'London',region:'UK'},
 {id:'Europe/Berlin',city:'Berlin',region:'Central Europe'},
 {id:'Asia/Dubai',city:'Dubai',region:'Gulf'},
 {id:'Asia/Kolkata',city:'Mumbai',region:'India'},
 {id:'Asia/Singapore',city:'Singapore',region:'Singapore'},
 {id:'Asia/Tokyo',city:'Tokyo',region:'Japan'},
 {id:'Australia/Sydney',city:'Sydney',region:'Australia East'}
];
function WorldClockBar(){
 const [now,setNow]=useState(()=>new Date());
 const [zones,setZones]=useState(()=>{try{const saved=JSON.parse(localStorage.getItem('intellistack-world-clocks')||'null');if(Array.isArray(saved)&&saved.length)return [...new Set(saved.filter(id=>WORLD_TIME_ZONES.some(z=>z.id===id)))];}catch{}return ['America/Chicago','America/Los_Angeles','America/New_York','Europe/London','Asia/Tokyo'];});
 const [newZone,setNewZone]=useState('Asia/Singapore');
 useEffect(()=>{const timer=setInterval(()=>setNow(new Date()),15000);return ()=>clearInterval(timer);},[]);
 const saveZones=(next)=>{setZones(next);try{localStorage.setItem('intellistack-world-clocks',JSON.stringify(next));}catch{}};
 const format=(zone,options)=>new Intl.DateTimeFormat('en-US',{timeZone:zone,...options}).format(now);
 const offset=(zone)=>{try{return new Intl.DateTimeFormat('en-US',{timeZone:zone,timeZoneName:'shortOffset'}).formatToParts(now).find(part=>part.type==='timeZoneName')?.value.replace('GMT','UTC')||'UTC';}catch{return 'UTC';}};
 const localWindow=(zone)=>{const parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,weekday:'short',hour:'2-digit',hourCycle:'h23'}).formatToParts(now);const weekday=parts.find(part=>part.type==='weekday')?.value;const hour=Number(parts.find(part=>part.type==='hour')?.value);return ['Mon','Tue','Wed','Thu','Fri'].includes(weekday)&&hour>=9&&hour<17;};
 const remaining=WORLD_TIME_ZONES.filter(zone=>!zones.includes(zone.id));
 return <section className="world-clock-bar" aria-label="Global operations world clocks">
  <div className="world-clock-toolbar">
   <div className="world-clock-title"><span className="world-clock-mark"><Globe2 size={16}/></span><div><b>GLOBAL TIME</b><small>ONE WORLD. ONE SYSTEM. ONE INTELLIGENT NETWORK.</small></div></div>
   <div className="world-clock-controls"><label htmlFor="world-clock-add">ADD A CITY</label><select id="world-clock-add" value={newZone} onChange={event=>setNewZone(event.target.value)} disabled={!remaining.length}><option value="">Choose city…</option>{remaining.map(zone=><option key={zone.id} value={zone.id}>{zone.city} · {zone.region}</option>)}</select><button type="button" className="world-clock-add" disabled={!remaining.length||!newZone} onClick={()=>{if(newZone&&!zones.includes(newZone)){saveZones([...zones,newZone]);setNewZone(remaining.find(zone=>zone.id!==newZone)?.id||'');}}}><Plus size={14}/> Add city</button></div>
  </div>
  <div className="world-clock-list">{zones.map(id=>{const zone=WORLD_TIME_ZONES.find(item=>item.id===id);if(!zone)return null;const inWindow=localWindow(id);return <div className="world-clock-card" key={id}><div className="world-clock-city"><b>{zone.city}</b><span>{zone.region}</span></div><strong>{format(id,{hour:'2-digit',minute:'2-digit',hour12:true})}</strong><div className="world-clock-meta"><span>{format(id,{weekday:'short',month:'short',day:'numeric'})}</span><span>{offset(id)}</span></div><span className={'world-clock-window '+(inWindow?'in-window':'out-window')}><i/>{inWindow?'9–5 local window':'Outside 9–5'}</span>{id!=='America/Chicago'&&<button type="button" className="world-clock-remove" onClick={()=>saveZones(zones.filter(item=>item!==id))} aria-label={'Remove '+zone.city+' clock'} title={'Remove '+zone.city}>×</button>}</div>})}</div>
  <div className="world-clock-footnote"><ShieldCheck size={13}/><span>The 9–5 indicator is a weekday local-time reference only—not a technician presence, shift assignment, or availability signal. Live staff availability requires verified schedules and presence data.</span></div>
 </section>;
}

