          <div className="theme-preview-top" style={{backgroundColor:theme.sidebar,backgroundImage:theme.images?.sidebar?'url("'+theme.images.sidebar+'")':undefined,borderColor:theme.border,borderStyle:theme.borderStyle||'solid'}}><span className="theme-preview-logo" style={{color:theme.accent,borderColor:theme.actionBorder}}><Shield size={18}/><b>IS</b></span><span><b>INTELLISTACK</b><small>SYSTEMS COMMAND</small></span><span className="theme-preview-menu">•••</span></div>
